  console.log(`  rc=${r.status}${r.signal ? ' signal=' + r.signal : ''}`);
  console.log(`  out=${JSON.stringify(out)}`);
  console.log(`  err=${JSON.stringify(err)}`);
}

// helper: build argv case files from a compact JS list
