// Reference model of the argparse CLI layer of test2.py, for differential validation.
export const PROG = 'test2_executable';
const HELP = { nargs: 0, names: ['-h', '--help'] };
const A = { nargs: 1, names: ['--a'], metavar: 'A', help: 'instance data (JSON string)' };
const B = { nargs: 1, names: ['--b'], metavar: 'B', help: 'schema (JSON string)' };
// insertion order is significant (ambiguity message order)
const OPTS = new Map([['-h', HELP], ['--help', HELP], ['--a', A], ['--b', B]]);
const NEG = /^-\d+$|^-\d*\.\d+$/;
const name = (act) => act.names.join('/');

function termWidth() {
  let c = 0;
  const v = process.env.COLUMNS;
  if (v !== undefined) { const n = parseInt(v, 10); if (String(n) === v.trim() && Number.isFinite(n)) c = n; }
  if (c <= 0) c = 80;                 // pipe fallback
  return c - 2;
}

// ---------- usage / help rendering ----------
function formatUsage(width) {
  const prefix = 'usage: ', prog = PROG;
  const optParts = ['[-h]', '--a', 'A', '--b', 'B'];
  const textWidth = width;
  const flat = optParts.join(' ');
  if (prefix.length + prog.length + 1 + flat.length <= textWidth) return prefix + prog + ' ' + flat;
  const getLines = (parts, indent, pre) => {
    const lines = []; let line = []; let ll = (pre !== undefined ? pre.length : indent.length) - 1;
    for (const p of parts) {
      if (ll + 1 + p.length > textWidth && line.length) { lines.push(indent + line.join(' ')); line = []; ll = indent.length - 1; }
      line.push(p); ll += 1 + p.length;
    }
    if (line.length) lines.push(indent + line.join(' '));
    if (pre !== undefined) lines[0] = lines[0].slice(indent.length);
    return lines;
  };
  let lines;
  if (prefix.length + prog.length <= 0.75 * textWidth) {
    lines = getLines([prog, ...optParts], ' '.repeat(prefix.length + prog.length + 1), prefix);
  } else {
    lines = [prog, ...getLines(optParts, ' '.repeat(prefix.length))];
  }
  return prefix + lines.join('\n');
}
function wrap(text, w) {
  const out = []; let cur = '';
  for (const word of text.split(' ')) {
    if (cur === '') cur = word;
    else if (cur.length + 1 + word.length <= w) cur += ' ' + word;
    else { out.push(cur); cur = word; }
  }
  if (cur) out.push(cur);
  return out;
}
export function formatHelp(width) {
  const ACTION_MAX_LENGTH = 12;               // len('-h, --help') + indent 2
  const mhp = Math.min(24, Math.max(width - 20, 4));
  const hp = Math.min(ACTION_MAX_LENGTH + 2, mhp);
  const hw = Math.max(width - hp, 11);
  const aw = hp - 4;
  let s = formatUsage(width) + '\n\noptions:\n';
  const rows = [['-h, --help', 'show this help message and exit'],
                ['--a A', 'instance data (JSON string)'],
                ['--b B', 'schema (JSON string)']];
  for (const [hdr, help] of rows) {
    const hl = wrap(help, hw);
    if (hdr.length <= aw) s += '  ' + hdr.padEnd(aw) + '  ' + hl[0] + '\n';
    else s += '  ' + hdr + '\n' + ' '.repeat(hp) + hl[0] + '\n';
    for (const l of hl.slice(1)) s += ' '.repeat(hp) + l + '\n';
  }
  return s;
}

// ---------- parsing ----------
class Exit { constructor(code, out, err) { Object.assign(this, { code, out, err }); } }
function fail(msg) {
  const w = termWidth();
  throw new Exit(2, '', formatUsage(w) + '\n' + PROG + ': error: ' + msg + '\n');
}
function optionTuples(s) {
  const res = [];
  if (s[0] === '-' && s[1] === '-') {
    let prefix = s, explicit = null;
    const eq = s.indexOf('=');
    if (eq !== -1) { prefix = s.slice(0, eq); explicit = s.slice(eq + 1); }
    for (const [os, act] of OPTS) if (os.startsWith(prefix)) res.push({ action: act, optString: os, sep: eq !== -1 ? '=' : '', explicit });
  } else {
    const optPrefix = s, shortPrefix = s.slice(0, 2), shortExplicit = s.slice(2);
    for (const [os, act] of OPTS) {
      if (os === shortPrefix) res.push({ action: act, optString: os, sep: '', explicit: shortExplicit });
      else if (os.startsWith(optPrefix)) res.push({ action: act, optString: os, sep: '', explicit: null });
    }
  }
  return res;
}
function parseOptional(s) {
  if (s === '') return null;
  if (s[0] !== '-') return null;
  if (OPTS.has(s)) return { action: OPTS.get(s), optString: s, sep: '', explicit: null };
  if (s.length === 1) return null;
  const eq = s.indexOf('=');
  if (eq !== -1) {
    const pre = s.slice(0, eq);
    if (OPTS.has(pre)) return { action: OPTS.get(pre), optString: pre, sep: '=', explicit: s.slice(eq + 1) };
  }
  const tuples = optionTuples(s);
  if (tuples.length > 1) fail(`ambiguous option: ${s} could match ${tuples.map(t => t.optString).join(', ')}`);
  if (tuples.length === 1) return tuples[0];
  if (NEG.test(s)) return null;
  if (s.includes(' ')) return null;
  return { action: null, optString: s, sep: '', explicit: null };
}

export function parse(argv) {
  const n = argv.length;
  const optIdx = new Map();
  let ddAt = -1;
  for (let i = 0; i < n; i++) {
    if (argv[i] === '--') { ddAt = i; break; }
    const t = parseOptional(argv[i]);
    if (t !== null) optIdx.set(i, t);
  }
  const isValue = (i) => i < n && !optIdx.has(i) && !(ddAt !== -1 && i === ddAt);
  const extras = [];
  const vals = {};
  const takeAction = (act, args, optString) => {
    if (act === HELP) throw new Exit(0, formatHelp(termWidth()), '');
    vals[act === A ? 'a' : 'b'] = args[0];
  };
  let i = 0;
  while (i < n) {
    if (!optIdx.has(i)) { extras.push(argv[i]); i++; continue; }
    let t = optIdx.get(i);
    const pending = [];
    let stop = i + 1;
    for (;;) {
      if (t.action === null) { extras.push(t.optString); break; }
      const act = t.action;
      if (t.explicit !== null) {
        if (act.nargs === 1) { pending.push([act, [t.explicit], t.optString]); break; }
        if (t.optString[1] !== '-' && t.explicit !== '') {
          if (t.sep === '=' || t.explicit[0] === '-') fail(`argument ${name(act)}: ignored explicit argument '${t.explicit}'`);
          pending.push([act, [], t.optString]);
          const newOpt = '-' + t.explicit[0];
          const rest = t.explicit.slice(1) || null;
          if (OPTS.has(newOpt)) { t = { action: OPTS.get(newOpt), optString: newOpt, sep: '', explicit: rest }; continue; }
          extras.push('-' + t.explicit); break;
        }
        fail(`argument ${name(act)}: ignored explicit argument '${t.explicit}'`);
      } else {
        if (act.nargs === 0) { pending.push([act, [], t.optString]); break; }
        if (!isValue(i + 1)) fail(`argument ${name(act)}: expected one argument`);
        pending.push([act, [argv[i + 1]], t.optString]); stop = i + 2; break;
      }
    }
    for (const [act, args, os] of pending) takeAction(act, args, os);
    i = stop;
  }
  const missing = [];
  if (vals.a === undefined) missing.push('--a');
  if (vals.b === undefined) missing.push('--b');
  if (missing.length) fail('the following arguments are required: ' + missing.join(', '));
  if (extras.length) fail('unrecognized arguments: ' + extras.join(' '));
  return vals;
}

export function runCli(argv) {
  try { const v = parse(argv); return { code: null, out: '', err: '', vals: v }; }
  catch (e) { if (e instanceof Exit) return { code: e.code, out: e.out, err: e.err, vals: null }; throw e; }
}
